for rid,r in old.items():
 if "exit=0" not in r["notes"]: continue
 t=(root/"corpus"/rec[rid]["patch"]).read_text(); files=re.findall(r"^diff --git a/(.*?) b/",t,re.M); expected=set(n.split("::")[0] for n in ms[r["instance_id"]]["fail_to_pass"]+ms[r["instance_id"]]["pass_to_pass"]); missingfiles=expected-set(files);
 if missingfiles!=expected: print(rid,"submitted required test file(s)",expected&set(files),"plugin", "report.outcome" in t)
'

